/**************************************************************/

/// Generates the entire Omni language surface from one table:
/// `OmniLanguages`/`OmniMetaLanguages` (the registries), `OmniLanguage`/
/// `OmniLanguagePost`/`OmniMetaLanguage` (the enum-dispatch wrappers), the
/// `DynOmni*` registries, and [`dict_omni_language`].
///
/// Each `languages` entry reads:
///
/// ```text
/// field if "feature" => Variant(LanguageTy, DynLanguageTy): ["canonical", "alias", ...];
/// ```
///
/// The `metas` section lists the subset of languages that can act as hosts
/// (drive expansion); languages absent from it are target-only.
macro_rules! define_omni {
    (
        languages {
            $( $field:ident if $feat:literal => $variant:ident($lang:ty, $dyn_lang:ty):
                [$canon:literal $(, $alias:literal)* $(,)?] );* $(;)?
        }
        metas {
            $( $mfield:ident if $mfeat:literal => $mvariant:ident($meta:ty):
                [$mcanon:literal $(, $malias:literal)* $(,)?] );* $(;)?
        }
    ) => {
        /// An "Omni"-language using enums.
        pub struct OmniLanguages {
            $(
                #[cfg(feature = $feat)]
                $field: OmniLanguage,
            )*
        }

        impl Default for OmniLanguages {
            #[allow(clippy::default_constructed_unit_structs)]
            fn default() -> Self {
                Self {
                    $(
                        #[cfg(feature = $feat)]
                        $field: OmniLanguage::$variant(<$lang>::default()),
                    )*
                }
            }
        }

        impl Languages for OmniLanguages {
            type Language = OmniLanguage;

            fn get(&self, lang: &str) -> Result<&Self::Language> {
                match lang {
                    $(
                        #[cfg(feature = $feat)]
                        $canon $(| $alias)* => Ok(&self.$field),
                    )*
                    _ => Err(miette!("{lang:?} can't be used as Language")),
                }
            }
            fn get_mut(&mut self, lang: &str) -> Result<&mut Self::Language> {
                match lang {
                    $(
                        #[cfg(feature = $feat)]
                        $canon $(| $alias)* => Ok(&mut self.$field),
                    )*
                    _ => Err(miette!("{lang:?} can't be used as Language")),
                }
            }
        }

        pub struct OmniMetaLanguages {
            $(
                #[cfg(feature = $mfeat)]
                $mfield: OmniMetaLanguage,
            )*
        }

        impl Default for OmniMetaLanguages {
            #[allow(clippy::default_constructed_unit_structs)]
            fn default() -> Self {
                Self {
                    $(
                        #[cfg(feature = $mfeat)]
                        $mfield: OmniMetaLanguage::$mvariant(<$meta>::default()),
                    )*
                }
            }
        }

        impl MetaLanguages for OmniMetaLanguages {
            type MetaLanguage = OmniMetaLanguage;

            fn get(&self, lang: &str) -> Result<&Self::MetaLanguage> {
                match lang {
                    $(
                        #[cfg(feature = $mfeat)]
                        $mcanon $(| $malias)* => Ok(&self.$mfield),
                    )*
                    _ => Err(miette!("{lang:?} can't be used as MetaLanguage")),
                }
            }
            fn get_mut(&mut self, lang: &str) -> Result<&mut Self::MetaLanguage> {
                match lang {
                    $(
                        #[cfg(feature = $mfeat)]
                        $mcanon $(| $malias)* => Ok(&mut self.$mfield),
                    )*
                    _ => Err(miette!("{lang:?} can't be used as MetaLanguage")),
                }
            }
        }

        /// A `Language` used by `Omni`.
        pub enum OmniLanguage {
            $(
                #[cfg(feature = $feat)]
                $variant($lang),
            )*
        }

        impl Language for OmniLanguage {
            type Post = OmniLanguagePost;

            #[allow(unused_variables)]
            fn parse_pre(
                &mut self,
                ikind: Option<InnerKind>,
                code: &[FlatNode],
            ) -> Result<Self::Post> {
                match self {
                    $(
                        #[cfg(feature = $feat)]
                        OmniLanguage::$variant(lang) => {
                            lang.parse_pre(ikind, code).map(OmniLanguagePost::$variant)
                        }
                    )*
                    #[allow(unreachable_patterns)]
                    _ => unreachable!(),
                }
            }

            fn hashbang(&self) -> Option<&'static str> {
                match self {
                    $(
                        #[cfg(feature = $feat)]
                        OmniLanguage::$variant(lang) => lang.hashbang(),
                    )*
                    #[allow(unreachable_patterns)]
                    _ => None,
                }
            }

            fn ident_tag(&self) -> &'static str {
                match self {
                    $(
                        #[cfg(feature = $feat)]
                        OmniLanguage::$variant(lang) => lang.ident_tag(),
                    )*
                    #[allow(unreachable_patterns)]
                    _ => "identifier",
                }
            }

            #[allow(unused_variables)]
            fn arity(&self, tag: &str) -> Arity {
                match self {
                    $(
                        #[cfg(feature = $feat)]
                        OmniLanguage::$variant(lang) => lang.arity(tag),
                    )*
                    #[allow(unreachable_patterns)]
                    _ => Default::default(),
                }
            }

            #[allow(unused_variables)]
            fn typ(&self, tag: &str) -> InnerKind {
                match self {
                    $(
                        #[cfg(feature = $feat)]
                        OmniLanguage::$variant(lang) => lang.typ(tag),
                    )*
                    #[allow(unreachable_patterns)]
                    _ => Default::default(),
                }
            }

            #[allow(unused_variables)]
            fn classify_term(&self, term: &QTerm) -> InnerKind {
                match self {
                    $(
                        #[cfg(feature = $feat)]
                        OmniLanguage::$variant(lang) => lang.classify_term(term),
                    )*
                    #[allow(unreachable_patterns)]
                    _ => Default::default(),
                }
            }
        }

        /// A `LanguagePost` used by `Omni`.
        #[derive(Debug)]
        pub enum OmniLanguagePost {
            $(
                #[cfg(feature = $feat)]
                $variant(<$lang as Language>::Post),
            )*
        }

        impl LanguagePost for OmniLanguagePost {
            fn holes(&self) -> &[Hole] {
                match self {
                    $(
                        #[cfg(feature = $feat)]
                        OmniLanguagePost::$variant(post) => post.holes(),
                    )*
                    #[allow(unreachable_patterns)]
                    _ => unreachable!(),
                }
            }

            #[allow(unused_variables)]
            fn parse_post(&self, plugs: &[Arc<QTerm>]) -> Result<Arc<QTerm>> {
                match self {
                    $(
                        #[cfg(feature = $feat)]
                        OmniLanguagePost::$variant(post) => post.parse_post(plugs),
                    )*
                    #[allow(unreachable_patterns)]
                    _ => unreachable!(),
                }
            }
        }

        /// A `MetaLanguage` used by `Omni`.
        pub enum OmniMetaLanguage {
            $(
                #[cfg(feature = $mfeat)]
                $mvariant($meta),
            )*
        }

        impl OmniMetaLanguage {
            fn inner(&self) -> &dyn MetaLanguage {
                match self {
                    $(
                        #[cfg(feature = $mfeat)]
                        OmniMetaLanguage::$mvariant(lang) => lang,
                    )*
                    #[allow(unreachable_patterns)]
                    _ => unreachable!(),
                }
            }
        }

        /// A `MultiLanguage` using `Box<dyn>`s.
        #[derive(Default)]
        pub struct DynOmniLanguages {
            $(
                #[cfg(feature = $feat)]
                $field: $dyn_lang,
            )*
        }

        impl Languages for DynOmniLanguages {
            type Language = dyn Language<Post = Box<dyn LanguagePost>>;

            fn get(&self, lang: &str) -> Result<&Self::Language> {
                match lang {
                    $(
                        #[cfg(feature = $feat)]
                        $canon $(| $alias)* => Ok(&self.$field),
                    )*
                    _ => Err(miette!("{lang:?} can't be used as Language")),
                }
            }
            fn get_mut(&mut self, lang: &str) -> Result<&mut Self::Language> {
                match lang {
                    $(
                        #[cfg(feature = $feat)]
                        $canon $(| $alias)* => Ok(&mut self.$field),
                    )*
                    _ => Err(miette!("{lang:?} can't be used as Language")),
                }
            }
        }

        /// A `MultiLanguage` using `Box<dyn>`s.
        #[derive(Default)]
        pub struct DynOmniMetaLanguages {
            $(
                #[cfg(feature = $mfeat)]
                $mfield: $meta,
            )*
        }

        impl MetaLanguages for DynOmniMetaLanguages {
            type MetaLanguage = dyn MetaLanguage;

            fn get(&self, lang: &str) -> Result<&Self::MetaLanguage> {
                match lang {
                    $(
                        #[cfg(feature = $mfeat)]
                        $mcanon $(| $malias)* => Ok(&self.$mfield),
                    )*
                    _ => Err(miette!("{lang:?} can't be used as MetaLanguage")),
                }
            }

            fn get_mut(&mut self, lang: &str) -> Result<&mut Self::MetaLanguage> {
                match lang {
                    $(
                        #[cfg(feature = $mfeat)]
                        $mcanon $(| $malias)* => Ok(&mut self.$mfield),
                    )*
                    _ => Err(miette!("{lang:?} can't be used as MetaLanguage")),
                }
            }
        }

        /// A `DictMulti` over all enabled languages. Each language is
        /// registered once under its canonical name; aliases resolve to that
        /// single instance through the alias registry.
        #[allow(clippy::default_constructed_unit_structs)]
        pub fn dict_omni_language() -> DictMulti {
            #[allow(unused_mut)]
            let mut ret = DictMulti::default();
            $(
                #[cfg(feature = $feat)]
                {
                    ret.add_lang($canon, bx(<$dyn_lang>::default()));
                    $( ret.add_alias($alias, $canon); )*
                }
            )*
            $(
                #[cfg(feature = $mfeat)]
                {
                    ret.add_meta($mcanon, bx(<$meta>::default()));
                    $( ret.add_alias($malias, $mcanon); )*
                }
            )*
            ret
        }

        /// The line-comment introducer for `lang`, by canonical name or alias —
        /// [`Comments::LINE`] of the language that name registers.
        ///
        /// Generated from the registry table, so a language's aliases cannot
        /// disagree about it and adding a language cannot forget it: every
        /// entry here has to implement [`Comments`] for the table to compile.
        ///
        /// `None` for a name no enabled feature registers, and for a language
        /// whose comments a *prefix* cannot express (HTML, plain text) — the
        /// caller decides the fallback.
        #[must_use]
        pub fn line_comment(lang: &str) -> Option<&'static str> {
            match lang {
                $(
                    #[cfg(feature = $feat)]
                    $canon $(| $alias)* => <$lang as crate::lang::Comments>::LINE,
                )*
                _ => None,
            }
        }

        /// The comment introducer for the `DO NOT EDIT` header the CLI writes
        /// onto a generated file of `lang` — [`Comments::HEADER`], which is
        /// [`line_comment`] for every language but Rust.
        ///
        /// The header has to be a comment *in the language just generated*
        /// (issue #136, where every language got Rust's `//!`); resolving it
        /// through the registry rather than a table of its own is issue #194.
        #[must_use]
        pub fn header_comment(lang: &str) -> Option<&'static str> {
            match lang {
                $(
                    #[cfg(feature = $feat)]
                    $canon $(| $alias)* => <$lang as crate::lang::Comments>::HEADER,
                )*
                _ => None,
            }
        }
    };
}

impl MetaLanguage for OmniMetaLanguage {
    fn expand_quote(
        &self,
        lang1: &str,
        tag: &str,
        i: Index,
        lang2: &str,
        qterm: &Arc<QTerm>,
        cmds: &[CmdOrHole],
    ) -> Result<Arc<QTerm>> {
        self.inner().expand_quote(lang1, tag, i, lang2, qterm, cmds)
    }

    fn expand_unquote(
        &self,
        lang1: &str,
        tag: &str,
        i: Index,
        lang2: &str,
        qterm: &Arc<QTerm>,
        cmds: &[CmdOrHole],
    ) -> Result<Arc<QTerm>> {
        self.inner()
            .expand_unquote(lang1, tag, i, lang2, qterm, cmds)
    }

    fn expand_tuple(
        &self,
        lang1: &str,
        tag: &str,
        qterms: &[Arc<QTerm>],
        cmds: &[CmdOrHole],
        arity: Arity,
    ) -> Result<Arc<QTerm>> {
        self.inner().expand_tuple(lang1, tag, qterms, cmds, arity)
    }

    fn wrap_child(&self, qterm: Arc<QTerm>, okind: OuterKind) -> Result<Arc<QTerm>> {
        self.inner().wrap_child(qterm, okind)
    }

    fn pattern_tag(&self) -> Option<&'static str> {
        self.inner().pattern_tag()
    }

    fn pattern_binding(&self, terms: &[Arc<QTerm>]) -> Option<(usize, usize)> {
        self.inner().pattern_binding(terms)
    }

    fn pattern_var(&self, name: &str) -> Result<Arc<QTerm>> {
        self.inner().pattern_var(name)
    }

    fn pattern_let(
        &self,
        names: &[Box<str>],
        pattern: &Arc<QTerm>,
        value: &Arc<QTerm>,
    ) -> Result<(Arc<QTerm>, Arc<QTerm>)> {
        self.inner().pattern_let(names, pattern, value)
    }

    fn lift_str(&self, target: &str) -> Result<&'static str> {
        self.inner().lift_str(target)
    }

    fn reduce_str(&self, target: &str) -> Result<&'static str> {
        self.inner().reduce_str(target)
    }

    fn emit_str(&self) -> Result<&'static str> {
        self.inner().emit_str()
    }

    fn type_str(&self) -> Result<&'static str> {
        self.inner().type_str()
    }

    fn name_str(&self) -> Result<&'static str> {
        self.inner().name_str()
    }
}

pub type Omni = Multi<OmniLanguages, OmniMetaLanguages>;

#[cfg(test)]
mod tests {
    use super::*;

    /// Aliases resolve through the registry to the canonical entry instead of
    /// owning a second instance.
    #[test]
    fn dict_aliases_resolve() {
        let dict = dict_omni_language();
        #[cfg(feature = "python")]
        {
            assert!(dict.get_lang("python").is_ok());
            assert!(dict.get_lang("py").is_ok());
            assert!(dict.get_meta("py").is_ok());
        }
        #[cfg(feature = "rust")]
        {
            assert!(dict.get_lang("rs").is_ok());
            assert!(dict.get_meta("rs").is_ok());
        }
        #[cfg(feature = "text")]
        {
            assert!(dict.get_lang("txt").is_ok());
            // text is target-only: the alias exists but has no meta entry
            assert!(dict.get_meta("txt").is_err());
        }
        #[cfg(feature = "lean")]
        {
            // Lean is both a target and a (string-based) host, under either
            // spelling.
            assert!(dict.get_lang("lean").is_ok());
            assert!(dict.get_lang("lean4").is_ok());
            assert!(dict.get_meta("lean").is_ok());
            assert!(dict.get_meta("lean4").is_ok());
        }
        assert!(dict.get_lang("nope").is_err());
    }

    /// Every registered language's comment spellings, pinned so that changing
    /// one is a deliberate edit here rather than a surprise in generated code.
    ///
    /// The header half is pinned again by the conformance battery, against the
    /// claim in `conformance/spec/<lang>.toml`. The line half has no spec claim
    /// — it is not a support-matrix axis, it feeds quilt-lsp's `CommentSyntax`
    /// — so this is where it is held, together with `quilt-lsp`'s
    /// `comment_syntax_comes_from_quilt`, which holds the server to it.
    #[test]
    fn comment_spellings() {
        // (name, line, header). Only Rust's two differ.
        let cases: &[(&str, Option<&str>, Option<&str>)] = &[
            #[cfg(feature = "bash")]
            ("bash", Some("#"), Some("#")),
            #[cfg(feature = "html")]
            ("html", None, None),
            #[cfg(feature = "lean")]
            ("lean", Some("--"), Some("--")),
            #[cfg(feature = "lean")]
            ("lean4", Some("--"), Some("--")),
            #[cfg(feature = "nix")]
            ("nix", Some("#"), Some("#")),
            #[cfg(feature = "python")]
            ("python", Some("#"), Some("#")),
            #[cfg(feature = "python")]
            ("py", Some("#"), Some("#")),
            #[cfg(feature = "rust")]
            ("rust", Some("//"), Some("//!")),
            #[cfg(feature = "rust")]
            ("rs", Some("//"), Some("//!")),
            #[cfg(feature = "sql")]
            ("sql", Some("--"), Some("--")),
            #[cfg(feature = "sql")]
            ("mysql", Some("--"), Some("--")),
            #[cfg(feature = "text")]
            ("text", None, None),
            #[cfg(feature = "typescript")]
            ("typescript", Some("//"), Some("//")),
            #[cfg(feature = "wgsl")]
            ("wgsl", Some("//"), Some("//")),
            #[cfg(feature = "zsh")]
            ("zsh", Some("#"), Some("#")),
        ];
        for (name, line, header) in cases {
            assert_eq!(line_comment(name), *line, "line_comment({name:?})");
            assert_eq!(header_comment(name), *header, "header_comment({name:?})");
        }
        // A name no language registers gets no answer, so callers can tell
        // "this language has no line comment" from "no such language".
        assert_eq!(line_comment("nope"), None);
        assert_eq!(header_comment("nope"), None);
    }
}

// Languages absent from `metas` (text, wgsl, html, sql) are target languages only —
// the host's MetaLanguage drives expansion. Nix, Lean and the two shells are
// both: quotable targets *and* string-based hosts (their metas generate code as
// strings, see `langs::nix::meta` / `langs::lean::meta` /
// `langs::shell::meta`).
define_omni! {
    languages {
        bash if "bash"   => Bash(BashLanguage, DynBashLanguage):       ["bash"];
        html if "html"   => Html(HtmlLanguage, DynHtmlLanguage):       ["html"];
        lean if "lean"   => Lean(LeanLanguage, DynLeanLanguage):       ["lean", "lean4"];
        nix  if "nix"    => Nix(NixLanguage, DynNixLanguage):          ["nix"];
        py   if "python" => Python(PythonLanguage, DynPythonLanguage): ["python", "py"];
        rs   if "rust"   => Rust(RustLanguage, DynRustLanguage):       ["rust", "rs"];
        sql  if "sql"    => Sql(SqlLanguage, DynSqlLanguage):          ["sql", "mysql", "mariadb"];
        txt  if "text"   => Text(TextLanguage, DynTextLanguage):       ["text", "txt"];
        ts   if "typescript" => TypeScript(TypeScriptLanguage, DynTypeScriptLanguage): ["typescript", "ts"];
        wgsl if "wgsl"   => Wgsl(WgslLanguage, DynWgslLanguage):       ["wgsl"];
        zsh  if "zsh"    => Zsh(ZshLanguage, DynZshLanguage):          ["zsh"];
    }
    metas {
        bash if "bash"   => Bash(BashMetaLanguage):                    ["bash"];
        lean if "lean"   => Lean(LeanMetaLanguage):                    ["lean", "lean4"];
        nix  if "nix"    => Nix(NixMetaLanguage):                      ["nix"];
        py   if "python" => Python(PythonMetaLanguage):                ["python", "py"];
        rs   if "rust"   => Rust(RustMetaLanguage):                    ["rust", "rs"];
        ts   if "typescript" => TypeScript(TypeScriptMetaLanguage):    ["typescript", "ts"];
        zsh  if "zsh"    => Zsh(ZshMetaLanguage):                      ["zsh"];
    }
}
